/**
 * Displays an error page
 */
export const getError = (

 options?: SecondParameter<typeof http>,signal?: AbortSignal
) => {


      return http<string>(
      {url: `/api/auth/error`, method: 'GET', signal
    },
      options);
    }




export const getGetErrorQueryKey = () => {
    return [
    `/api/auth/error`
    ] as const;
    }


export const getGetErrorQueryOptions = <TData = Awaited<ReturnType<typeof getError>>, TError = ErrorType<GetError400 | GetError401 | GetError403 | GetError404 | GetError429 | GetError500>>( options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof getError>>, TError, TData>>, request?: SecondParameter<typeof http>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetErrorQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getError>>> = ({ signal }) => getError(requestOptions, signal);





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getError>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

